def extract_values_from_filename(filename, logger):
    # Define the pattern to match Hs, T, WD, and seed values
    pattern = r"Hs(\d+\.\d{2})_T(\d+\.\d{2})_WD(\d+)_seed(\d+)\.yml"

    # Use re.search to find matches
    match = re.search(pattern, filename)

    if match:
        hs = float(match.group(1))  # Extract Hs value
        t = float(match.group(2))  # Extract T value
        wave_dir = int(match.group(3))  # Extract WD value
        seed = int(match.group(4))  # Extract seed value
        return {"hs": hs, "t": t, "wave_dir": wave_dir, "seed": seed}
    else:
        logger.error(f"Failed to extract values from filename: {filename}")
        sys.exit(1)
        sys.exit(1)


def get_unc_path(logger):
    """
    Returns the UNC path of the current working folder on a mapped network drive.
    If running on a local drive (e.g., C:\, D:\, etc.), returns the local path as-is.
    If the path is already a UNC path, returns it unchanged.
    """
    try:
        current_path = os.getcwd()

        # If it's already a UNC path, just return it
        if current_path.startswith("\\\\"):
            return current_path

        # Extract the drive (e.g., 'X:') from the path
        drive, _ = os.path.splitdrive(current_path)

        # Try to get network/mapping info for the drive.
        # If this fails, it's a local drive — return the path as-is.
        try:
            net_info = win32net.NetUseGetInfo("", drive)
        except Exception:
            return current_path

        # If we have mapping info, build the UNC path
        share_path = net_info.get("remote")
        if not share_path:
            # No remote share: treat as local
            return current_path

        # Construct UNC using the share root + relative path
        relative_path = current_path[len(drive) :]  # keep leading backslash
        full_unc_path = (
            share_path.rstrip("\\") + "\\" + relative_path.lstrip("\\")
        )

        return full_unc_path.replace("/", "\\")
    except Exception as e:
        logger.error(f"Error converting to UNC path: {e}")
        sys.exit(1)


def write_failed_json(base_name, bisection, reason=None, retry_bisection=None):
    """
    Writes a _failed.json marker file to indicate that a run has failed.

    Args:
        base_name (str): Base filename (e.g. 'Hs1.50_T08.00_WD180_seed1')
        bisection (int): The bisection number at which the failure occurred.
        reason (str, optional): Description of the failure reason.
        retry_bisection (int, optional): If set, indicates that bisect.main()
            has already prepared the YAML with a halved timestep for this
            bisection attempt.  create_txt_package() uses this to decide
            whether the file should be re-run or skipped on restart.
    """
    failed_path = os.path.join("runs", base_name + "_failed.json")
    payload = {
        "bisection": bisection,
        "reason": reason,
        "timestamp": datetime.now(timezone.utc).isoformat(),
    }
    if retry_bisection is not None:
        payload["retry_bisection"] = retry_bisection
    with open(failed_path, "w", encoding="utf-8") as f:
        json.dump(payload, f, indent=2)


def delete_failed_json(base_name):
    """
    Deletes a _failed.json marker file if it exists.

    Args:
        base_name (str): Base filename (e.g. 'Hs1.50_T08.00_WD180_seed1')

    Returns:
        bool: True if deleted, False otherwise.
    """
    failed_path = os.path.join("runs", base_name + "_failed.json")
    try:
        os.remove(failed_path)
        return True
    except FileNotFoundError:
        return False


def create_txt_package(config, logger):
    """
    Creates a text file of files to run.

    The text file contains:
     - list of all yaml files for the current step (files listed as Q in db)

     Args:
        config (dict): Configuration dictionary

    Returns:
        str: The name of the text file created.
    """
    logger.info("Creating text file of files to run...")

    txt_file = "submit.txt"

    yml_files = []
    # Open sql database and get a list of files that are required to be run
    # in the current step.
    with sqlite3.connect(cfg.LOCAL_DB_PATH) as conn:
        cursor = conn.cursor()

        # Retrieve cases with status 'Q' or 'Q+'
        # Also need to retrieve cases that have a 'Fi' status where
        # i <= max_bisections
        max_bisections = config.get("max_bisections")
        statuses = ["Q", "Q+", "F"] + [
            f"F{i}" for i in range(max_bisections + 1)
        ]
        placeholders = ",".join("?" for _ in statuses)

        sql = f"""
        SELECT rowid, hs, period, wave_dir, seed_number, seed_value
        FROM seed_results
        WHERE status IN ({placeholders})
        """

        custom_execute(cursor, sql, statuses)

        rows = cursor.fetchall()

    for row in rows:
        rowid, hs, period, wave_dir, seed_number, seed_value = row

        # Create a YAML file for each case
        base_name = utils_core.file_name_gen(hs, period, wave_dir, seed_number)
        yml_name = base_name + ".yml"
        json_name = base_name + "_results.json"

        # Check to see if results json file exists — no need to re-run.
        # Also check for a _failed.json marker:
        #   - If it contains "retry_bisection", bisect.main() already
        #     prepared the YAML with a halved timestep → allow re-run
        #     and delete the stale marker.
        #   - If it does NOT contain "retry_bisection", the failure
        #     has not been followed by a bisection → skip on restart
        #     and mark the seed/stat/case as failed in the database.
        failed_path = os.path.join("runs", base_name + "_failed.json")
        if os.path.isfile(os.path.join("runs", json_name)):
            continue
        if os.path.isfile(failed_path):
            try:
                with open(failed_path, "r", encoding="utf-8") as f:
                    failed_data = json.load(f)
            except Exception:
                failed_data = {}
            if "retry_bisection" in failed_data:
                # Bisection prepared a new attempt — delete marker, allow re-run
                delete_failed_json(base_name)
            else:
                # No retry prepared — mark as permanently failed in the database
                # so downstream code (store_results, run_stats) skips this seed.
                bisection = failed_data.get("bisection", 0)
                seed_results_update(hs, period, wave_dir, seed_number, "F")
                stat_results_update(hs, period, wave_dir, "NG")
                case_results_update(hs, period, "NG")
                logger.info(
                    f"Skipping {base_name} — previous failure at bisection "
                    f"{bisection} (no retry prepared)"
                )
                continue
        yml_files.append(yml_name)

    if len(yml_files) == 0:
        logger.info(
            "JSON files already exist for all cases, no need to run YML files."
        )
        return None, []

    # Write the YML files to the text file
    with open("runs/" + txt_file, "w") as f:
        for yml_file in yml_files:
            f.write(yml_file + "\n")

    # Add UNC path to all yml files in list using get_unc_path_cwd
    yml_files = [
        get_unc_path(logger) + "\\runs\\" + yml_file for yml_file in yml_files
    ]

    return txt_file, yml_files
